import type { Metadata } from "next";
import { SITE } from "./jsonld";

type OpenGraph = NonNullable<Metadata["openGraph"]>;
type Twitter = NonNullable<Metadata["twitter"]>;

export const RSS_URL = `${SITE}/blog/rss.xml`;

/** Generated by scripts/blog/prepare.ts on every build, even when the blog is disabled. */
export const BLOG_OG_IMAGE = { url: `${SITE}/images/blog/_og/_blog.png`, width: 1200, height: 630, alt: "Lidr.io blog" };

/**
 * Next merges metadata shallowly: a page's `openGraph` replaces the layout's whole object,
 * so every blog page has to restate the site-wide defaults. `og` wins over the defaults.
 */
export function blogOpenGraph(og: OpenGraph): OpenGraph {
  return { siteName: "Lidr.io", locale: "en_US", type: "website", images: [BLOG_OG_IMAGE], ...og } as OpenGraph;
}

export function blogTwitter(title: string, description: string, imageUrl: string = BLOG_OG_IMAGE.url): Twitter {
  return { card: "summary_large_image", title, description, images: [imageUrl] };
}
